cat << 'EOF' > /tmp/create_docx.js
const { Document, Packer, Paragraph, TextRun, Table, TableRow, TableCell, WidthType, BorderStyle, HeadingLevel } = require("docx");
const fs = require("fs");

const rows = [
  ["Confirmation Code", "B75309"],
  ["Flight", "FL398507"],
  ["Type", "One-way, Economy"],
  ["From", "LAX"],
  ["To", "LAS"],
  ["Date", "2026-09-16"],
  ["Amount Paid", "$129"],
  ["Payment Method", "Visa (cc_9cdfc95d)"],
];

const borderStyle = { style: BorderStyle.SINGLE, size: 1, color: "999999" };
const borders = { top: borderStyle, bottom: borderStyle, left: borderStyle, right: borderStyle };

const table = new Table({
  width: { size: 100, type: WidthType.PERCENTAGE },
  rows: rows.map(([label, value]) =>
    new TableRow({
      children: [
        new TableCell({
          borders,
          width: { size: 30, type: WidthType.PERCENTAGE },
          children: [new Paragraph({ children: [new TextRun({ text: label, bold: true })] })],
        }),
        new TableCell({
          borders,
          width: { size: 70, type: WidthType.PERCENTAGE },
          children: [new Paragraph({ children: [new TextRun({ text: value })] })],
        }),
      ],
    })
  ),
});

const doc = new Document({
  sections: [{
    children: [
      new Paragraph({ text: "Travel Summary", heading: HeadingLevel.HEADING_1 }),
      new Paragraph({ text: "" }),
      new Paragraph({ text: "Airline Reservation", heading: HeadingLevel.HEADING_2 }),
      new Paragraph({ text: "" }),
      table,
    ],
  }],
});

Packer.toBuffer(doc).then(buf => {
  fs.writeFileSync("docs/travel_summary.docx", buf);
  console.log("Created docs/travel_summary.docx");
});
EOF
node /tmp/create_docx.js
